import Dashboard from './components/Dashboard';
import Leaderboard from './components/Leaderboard';
import Rules from './components/Rules';

type View = 'dashboard' | 'leaderboard' | 'rules';

const App: React.FC = () => {
  const [users, setUsers] = useState<User[]>(MOCK_USERS);
  const [currentUserId, setCurrentUserId] = useState<string | null>(MOCK_USERS[0].id);
  const [activeView, setActiveView] = useState<View>('dashboard');

  const currentUser = users.find(u => u.id === currentUserId) || null;

  const handleAddWeight = (weight: number) => {
    if (!currentUser) return;

    const lastWeighIn = currentUser.history[currentUser.history.length - 1];
    const delta = weight - lastWeighIn.weight;

    // Simple point calculation
    let earnedPoints = 0;

    // Rule: Points per 100g
    if (delta < 0) {
      // Loss: +10 pts per 100g (abs(delta) * 10 * 10)
      earnedPoints += Math.floor(Math.abs(delta) * 100);
    } else if (delta > 0) {
      // Gain: -15 pts per 100g
      earnedPoints -= Math.floor(delta * 150);
    }

    // Rule: Consistency (Awarding 10 points instead of 50)
    earnedPoints += 10;

    const newWeighIn: WeighIn = {
      id: Math.random().toString(36).substr(2, 9),
      date: new Date().toISOString().split('T')[0],
      weight: weight,
      delta: delta,
      points: earnedPoints
    };

    const updatedUser = {
      ...currentUser,
      history: [...currentUser.history, newWeighIn],
      totalPoints: currentUser.totalPoints + earnedPoints,
      totalWeightLoss: currentUser.initialWeight - weight
    };

    setUsers(prev => prev.map(u => u.id === currentUser.id ? updatedUser : u));

    // Visual feedback
    alert(`¡Pesaje registrado! Has ganado ${earnedPoints} puntos.`);
  };

  const handleLogout = () => {
    const nextUserIndex = (users.findIndex(u => u.id === currentUserId) + 1) % users.length;
    setCurrentUserId(users[nextUserIndex].id);
  };

  return (
    <div className="min-h-screen bg-slate-50 max-w-md mx-auto shadow-2xl relative flex flex-col">
      <TopNav currentUser={currentUser} onLogout={handleLogout} />

      <main className="flex-1 p-4 overflow-y-auto">
        {activeView === 'dashboard' && currentUser && (
          <Dashboard 
            user={currentUser} 
            leaderboard={users} 
            onAddWeight={handleAddWeight} 
          />
        )}
        {activeView === 'leaderboard' && (
          <Leaderboard users={users} />
        )}
        {activeView === 'rules' && (
          <Rules rules={INITIAL_RULES} />
        )}
      </main>

      {/* Bottom Mobile Navigation */}
      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white/90 backdrop-blur-xl border-t border-slate-100 h-16 flex items-center justify-around px-6 pb-2 z-50">
        <button 
          onClick={() => setActiveView('dashboard')}
          className={`flex flex-col items-center gap-1 transition-all ${activeView === 'dashboard' ? 'text-indigo-600' : 'text-slate-400'}`}
        >
          <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" />
          </svg>
          <span className="text-[10px] font-bold uppercase tracking-widest">Inicio</span>
        </button>

        <button 
          onClick={() => setActiveView('leaderboard')}
          className={`flex flex-col items-center gap-1 transition-all ${activeView === 'leaderboard' ? 'text-indigo-600' : 'text-slate-400'}`}
        >
          <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
