import React, { useEffect, useState } from 'react';
import { User, WeighIn } from '../types';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area } from 'recharts';
import { getMotivationalMessage } from '../services/geminiService';

interface DashboardProps {
  user: User;
  leaderboard: User[];
  onAddWeight: (weight: number, ateOut: boolean) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, leaderboard, onAddWeight }) => {
  const [newWeight, setNewWeight] = useState('');
  const [ateOut, setAteOut] = useState(false);
  const [aiMessage, setAiMessage] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  useEffect(() => {
    const fetchMessage = async () => {
      setLoadingAi(true);
      const msg = await getMotivationalMessage(user, leaderboard);
      setAiMessage(msg || null);
      setLoadingAi(false);
    };
    fetchMessage();
  }, [user.id, leaderboard.length]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const weight = parseFloat(newWeight);
    if (!isNaN(weight) && weight > 0) {
      onAddWeight(weight, ateOut);
      setNewWeight('');
      setAteOut(false);
    }
  };

  const chartData = user.history.map((h, index) => {
    let accumulated = 0;
    for(let i=0; i<=index; i++) accumulated += user.history[i].delta;
    return {
      name: `S${index}`,
      pérdida: Math.abs(accumulated).toFixed(1),
      puntos: h.points
    };
  });

  return (
    <div className="space-y-6 pb-20">
      <div className="bg-gradient-to-br from-indigo-500 to-purple-600 rounded-3xl p-6 text-white shadow-xl relative overflow-hidden">
        <div className="relative z-10">
          <p className="text-indigo-100 text-sm font-medium mb-1">Tu progreso hoy</p>
          <h2 className="text-2xl font-bold mb-4 italic">
            {loadingAi ? 'Consultando a tu coach IA...' : aiMessage}
          </h2>
          <div className="grid grid-cols-2 gap-4">
            <div className="bg-white/10 backdrop-blur-md rounded-2xl p-3">
              <p className="text-xs text-indigo-100">Puntos Totales</p>
              <p className="text-xl font-bold">{user.totalPoints} pts</p>
            </div>
            <div className="bg-white/10 backdrop-blur-md rounded-2xl p-3">
              <p className="text-xs text-indigo-100">Pérdida Total</p>
              <p className="text-xl font-bold">{user.totalWeightLoss.toFixed(1)} kg</p>
            </div>
          </div>
        </div>
        <div className="absolute top-[-20%] right-[-10%] w-40 h-40 bg-white/10 rounded-full blur-3xl"></div>
      </div>

      <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-4">Curva de Esfuerzo</h3>
        <div className="h-48 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={chartData}>
              <defs>
                <linearGradient id="colorLoss" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3}/>
                  <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                </linearGradient>
              </defs>
              <Tooltip 
                contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
                labelStyle={{ fontWeight: 'bold' }}
              />
              <Area type="monotone" dataKey="pérdida" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorLoss)" />
            </AreaChart>
          </ResponsiveContainer>
        </div>
        <p className="text-xs text-center text-slate-400 mt-2">Seguimiento de kilos perdidos acumulados</p>
      </div>

      <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-4">Registrar Peso</h3>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="flex gap-2">
            <div className="relative flex-1">
              <input 
                type="number" 
                step="0.1"
                value={newWeight}
                onChange={(e) => setNewWeight(e.target.value)}
                placeholder="Tu peso hoy..."
                className="w-full bg-slate-50 border-none rounded-2xl py-3 px-4 text-slate-700 focus:ring-2 focus:ring-indigo-500 transition-all outline-none"
              />
              <span className="absolute right-4 top-3 text-slate-400 font-medium">kg</span>
            </div>
            <button 
              type="submit"
              className="bg-indigo-600 text-white font-bold py-3 px-6 rounded-2xl hover:bg-indigo-700 active:scale-95 transition-all shadow-lg shadow-indigo-100"
            >
              Enviar
            </button>
          </div>

          <label className="flex items-center gap-3 p-3 bg-slate-50 rounded-2xl cursor-pointer select-none active:bg-slate-100 transition-colors">
            <input 
              type="checkbox" 
              checked={ateOut}
              onChange={(e) => setAteOut(e.target.checked)}
              className="w-5 h-5 rounded-lg border-slate-300 text-indigo-600 focus:ring-indigo-500"
            />
            <div className="flex-1">
              <p className="text-sm font-bold text-slate-700">¿Comiste fuera ayer?</p>
              <p className="text-[10px] text-slate-500 uppercase font-bold tracking-tight">¡Bono Social de +50 pts!</p>
            </div>
            <span className="text-xl">🍽️</span>
          </label>
        </form>
        <p className="text-[10px] text-slate-400 mt-3 text-center uppercase tracking-wider font-semibold">
          Tu peso real solo lo ves tú. El grupo solo verá tus puntos y porcentaje.
        </p>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { User, WeighIn, AppState } from './types';
import { MOCK_USERS, INITIAL_RULES } from './constants';
import TopNav from './components/TopNav';
import Dashboard from './components/Dashboard';
import Leaderboard from './components/Leaderboard';
import Rules from './components/Rules';

type View = 'dashboard' | 'leaderboard' | 'rules';

const App: React.FC = () => {
  const [users, setUsers] = useState<User[]>(MOCK_USERS);
  const [currentUserId, setCurrentUserId] = useState<string | null>(MOCK_USERS[0].id);
  const [activeView, setActiveView] = useState<View>('dashboard');

  const currentUser = users.find(u => u.id === currentUserId) || null;

  const handleAddWeight = (weight: number, ateOut: boolean) => {
    if (!currentUser) return;

    const lastWeighIn = currentUser.history[currentUser.history.length - 1];
    const delta = weight - lastWeighIn.weight;

    // Simple point calculation
    let earnedPoints = 0;

    // Rule: Points per 100g
    if (delta < 0) {
      // Loss: +10 pts per 100g (abs(delta) * 10 * 10)
      earnedPoints += Math.floor(Math.abs(delta) * 100);
    } else if (delta > 0) {
      // Gain: -15 pts per 100g
      earnedPoints -= Math.floor(delta * 150);
    }

    // Rule: Consistency (10 points)
    earnedPoints += 10;

    // New Rule: Ate Out Bonus (50 points)
    if (ateOut) {
      earnedPoints += 50;
    }

    const newWeighIn: WeighIn = {
      id: Math.random().toString(36).substr(2, 9),
      date: new Date().toISOString().split('T')[0],
      weight: weight,
      delta: delta,
      points: earnedPoints,
      ateOut: ateOut
    };

    const updatedUser = {
      ...currentUser,
      history: [...currentUser.history, newWeighIn],
      totalPoints: currentUser.totalPoints + earnedPoints,
      totalWeightLoss: currentUser.initialWeight - weight
    };

    setUsers(prev => prev.map(u => u.id === currentUser.id ? updatedUser : u));

    // Visual feedback
    alert(`¡Peso registrado! Has obtenido un total de ${earnedPoints} puntos.`);
  };

  const handleLogout = () => {
    const nextUserIndex = (users.findIndex(u => u.id === currentUserId) + 1) % users.length;
    setCurrentUserId(users[nextUserIndex].id);
  };

  return (
    <div className="min-h-screen bg-slate-50 max-w-md mx-auto shadow-2xl relative flex flex-col">
      <TopNav currentUser={currentUser} onLogout={handleLogout} />

      <main className="flex-1 p-4 overflow-y-auto">
        {activeView === 'dashboard' && currentUser && (
          <Dashboard 
            user={currentUser} 
            leaderboard={users} 
            onAddWeight={handleAddWeight} 
          />
        )}
        {activeView === 'leaderboard' && (
          <Leaderboard users={users} />
        )}
        {activeView === 'rules' && (
          <Rules rules={INITIAL_RULES} />
        )}
      </main>

      {/* Bottom Mobile Navigation */}
      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white/90 backdrop-blur-xl border-t border-slate-100 h-16 flex items-center justify-around px-6 pb-2 z-50">
        <button 
          onClick={() => setActiveView('dashboard')}
          className={`flex flex-col items-center gap-1 transition-all ${activeView === 'dashboard' ? 'text-indigo-600' : 'text-slate-400'}`}
        >
          <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" />
          </svg>
          <span className="text-[10px] font-bold uppercase tracking-widest">Inicio</span>
        </button>

        <button 
          onClick={() => setActiveView('leaderboard')}
          className={`flex flex-col items-center gap-1 transition-all ${activeView === 'leaderboard' ? 'text-indigo-600' : 'text-slate-400'}`}
        >
          <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
          </svg>
          <span className="text-[10px] font-bold uppercase tracking-widest">Ranking</span>
        </button>

        <button 
          onClick={() => setActiveView('rules')}
          className={`flex flex-col items-center gap-1 transition-all ${activeView === 'rules' ? 'text-indigo-600' : 'text-slate-400'}`}
        >
          <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
          </svg>
          <span className="text-[10px] font-bold uppercase tracking-widest">Reglas</span>
        </button>
      </nav>
    </div>
  );
};

