import { GoogleGenAI } from "@google/genai";
import { User } from "../types";

export const getMotivationalMessage = async (user: User, leaderboard: User[]) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const position = leaderboard.findIndex(u => u.id === user.id) + 1;
  const lastChange = user.history.length > 0 ? user.history[user.history.length - 1].delta : 0;

  const prompt = `
    Contexto: Un reto de pérdida de peso grupal basado en puntos.
    Usuario: ${user.realName} (Pseudónimo: ${user.pseudonym})
    Puesto actual: ${position} de ${leaderboard.length}
    Último cambio de peso: ${lastChange} kg (${lastChange < 0 ? 'perdió' : 'ganó'})
    Puntos totales: ${user.totalPoints}

    Genera un mensaje corto y motivador (máximo 2 frases) en español para este usuario.
    REGLA IMPORTANTE: Dirígete a él por su pseudónimo "${user.pseudonym}", nunca uses su nombre real.
    Si va ganando, anímalo a seguir así. Si va perdiendo, dale ánimos y un pequeño consejo de salud.
    No menciones el peso exacto, solo el progreso y los puntos.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Error fetching Gemini message:", error);
    return `¡Sigue esforzándote ${user.pseudonym}! Cada paso cuenta en este camino a la salud.`;
  }
};

