import { GoogleGenAI } from "@google/genai";
import { User } from "../types";

export const getMotivationalMessage = async (user: User, leaderboard: User[]) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const position = leaderboard.findIndex(u => u.id === user.id) + 1;
  const lastChange = user.history.length > 0 ? user.history[user.history.length - 1].delta : 0;

  const prompt = `
    Contexto: Un reto de pérdida de peso entre amigos basado en puntos.
    Usuario: ${user.realName} (Pseudónimo: ${user.pseudonym})
    Puesto actual: ${position} de ${leaderboard.length}
    Último registro: ${lastChange === 0 ? 'empezando' : lastChange < 0 ? 'ha bajado peso' : 'ha subido un poco'}
    Puntos totales: ${user.totalPoints}

    Genera un mensaje MUY INFORMAL y divertido (máximo 2 frases cortas) en español de España.
    REGLAS DE ESTILO:
    - Habla como un colega en un grupo de WhatsApp. Usa "tú".
    - Usa expresiones naturales como: "¡A tope!", "¡Vaya crack!", "Ni tan mal", "Dale caña", "Ojo ahí", "A seguir dándole".
    - Dirígete a él SOLO por su pseudónimo "${user.pseudonym}".
    - Si va en los primeros puestos, sé un poco "fan".
    - Si ha subido de peso, no seas serio, dile algo tipo "no pasa nada, mañana se entrena el doble" o "las bravas de ayer pesaron, ¿eh?".
    - Si va último, dale ánimos con humor.
    - Usa emojis divertidos.
    - NUNCA menciones kilos exactos ni seas formal.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Error fetching Gemini message:", error);
    const defaults = [
      `¡A tope ${user.pseudonym}! ¡Dale caña que tú puedes! 💪`,
      `¿Cómo va eso, ${user.pseudonym}? ¡A seguir sumando puntos! 🔥`,
      `¡Vaya crack estás hecho, ${user.pseudonym}! Ni un paso atrás. 🚀`
    ];
    return defaults[Math.floor(Math.random() * defaults.length)];
  }
};

import React, { useState } from 'react';
import { User, WeighIn, CompetitionConfig } from './types';
import { MOCK_USERS, INITIAL_RULES, COMPETITION_CONFIG } from './constants';
import TopNav from './components/TopNav';
import Dashboard from './components/Dashboard';
import Leaderboard from './components/Leaderboard';
import Rules from './components/Rules';
import AdminSettings from './components/AdminSettings';
import LandingPage from './components/LandingPage';

type View = 'dashboard' | 'leaderboard' | 'rules' | 'admin' | 'welcome';

const App: React.FC = () => {
  const [users, setUsers] = useState<User[]>(MOCK_USERS);
  const [currentUserId, setCurrentUserId] = useState<string | null>(null); 
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [competitionConfig, setCompetitionConfig] = useState<CompetitionConfig>(COMPETITION_CONFIG);

  const currentUser = users.find(u => u.id === currentUserId) || null;

  const handleAddWeight = (weight: number, ateOut: boolean) => {
    if (!currentUser) return;

    const today = new Date().toISOString().split('T')[0];
    const alreadyRegistered = currentUser.history.some(h => h.date === today);

    if (alreadyRegistered) {
      alert("Ya has registrado tu peso hoy.");
      return;
    }

    const lastWeighIn = currentUser.history.length > 0 
      ? currentUser.history[currentUser.history.length - 1] 
      : { weight: currentUser.initialWeight };

    const delta = weight - lastWeighIn.weight;

    let earnedPoints = 0;

    if (delta < 0) {
      earnedPoints += Math.floor(Math.abs(delta) * 100);
    } else if (delta > 0) {
      earnedPoints -= Math.floor(delta * 150);
    }

    earnedPoints += 10; 

    if (ateOut) {
      earnedPoints += 50;
    }

    const newWeighIn: WeighIn = {
      id: Math.random().toString(36).substr(2, 9),
      date: today,
      weight: weight,
      delta: delta,
      points: earnedPoints,
      ateOut: ateOut
    };

    const updatedUser = {
      ...currentUser,
      history: [...currentUser.history, newWeighIn],
      totalPoints: currentUser.totalPoints + earnedPoints,
      totalWeightLoss: currentUser.initialWeight - weight
    };

    setUsers(prev => prev.map(u => u.id === currentUser.id ? updatedUser : u));
    alert(`¡Peso registrado! Has obtenido ${earnedPoints} puntos.`);
  };

  const handleRemoveUser = (userId: string) => {
    if (userId === currentUserId) {
      alert("No puedes eliminarte a ti mismo.");
      return;
    }
    setUsers(prev => prev.filter(u => u.id !== userId));
  };

  const handleToggleAdmin = (userId: string) => {
    if (userId === currentUserId) {
      alert("No puedes quitarte los permisos de administrador a ti mismo para no quedar bloqueado.");
      return;
    }
    setUsers(prev => prev.map(u => u.id === userId ? { ...u, isAdmin: !u.isAdmin } : u));
  };

  const handleRegister = (userData: { realName: string, pseudonym: string, initialWeight: number }) => {
    const newId = Math.random().toString(36).substr(2, 9);
    const newUser: User = {
      id: newId,
      realName: userData.realName,
      pseudonym: userData.pseudonym,
      initialWeight: userData.initialWeight,
      avatar: `https://picsum.photos/seed/${userData.pseudonym}/200`,
      history: [],
      totalPoints: 0,
      totalWeightLoss: 0,
      isAdmin: users.length === 0 
    };

    setUsers(prev => [...prev, newUser]);
    setCurrentUserId(newId);
    setActiveView('dashboard');
  };

  const handleAddUserAdmin = (userData: { realName: string, pseudonym: string, initialWeight: number }) => {
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      realName: userData.realName,
      pseudonym: userData.pseudonym,
      initialWeight: userData.initialWeight,
      avatar: `https://picsum.photos/seed/${userData.pseudonym}/200`,
      history: [],
      totalPoints: 0,
      totalWeightLoss: 0,
      isAdmin: false
    };

    setUsers(prev => [...prev, newUser]);
  };

  const handleLogout = () => {
    // Para esta versión simulamos un cambio de perfil cíclico si hay varios
    if (users.length > 0) {
      const currentIndex = users.findIndex(u => u.id === currentUserId);
      const nextUserIndex = (currentIndex + 1) % users.length;
      setCurrentUserId(users[nextUserIndex].id);
      setActiveView('dashboard');
    } else {
      setCurrentUserId(null);
      setActiveView('welcome');
    }
  };

  if (!currentUser && users.length > 0 && !currentUserId) {
    // Si hay usuarios pero no estamos logueados, mostramos landing o forzamos el primero por sencillez
    return (
        <div className="min-h-screen bg-slate-50 max-w-md mx-auto shadow-2xl relative flex flex-col">
          <TopNav currentUser={null} onLogout={() => {}} />
          <main className="flex-1 p-4 overflow-y-auto">
            <LandingPage onRegister={handleRegister} />
          </main>
        </div>
      );
  }

  if (users.length === 0) {
    return (
      <div className="min-h-screen bg-slate-50 max-w-md mx-auto shadow-2xl relative flex flex-col">
        <TopNav currentUser={null} onLogout={() => {}} />
        <main className="flex-1 p-4 overflow-y-auto">
          <LandingPage onRegister={handleRegister} />
        </main>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 max-w-md mx-auto shadow-2xl relative flex flex-col">
      <TopNav currentUser={currentUser} onLogout={handleLogout} />

      <main className="flex-1 p-4 overflow-y-auto">
        {activeView === 'dashboard' && currentUser && (
          <Dashboard 
            user={currentUser} 
            leaderboard={users} 
            onAddWeight={handleAddWeight} 
            config={competitionConfig}
          />
        )}
        {activeView === 'leaderboard' && (
          <Leaderboard users={users} currentUser={currentUser} config={competitionConfig} />
        )}
        {activeView === 'rules' && (
          <Rules rules={INITIAL_RULES} />
        )}
        {activeView === 'admin' && currentUser?.isAdmin && (
          <AdminSettings 
            config={competitionConfig} 
            onUpdateConfig={setCompetitionConfig} 
            users={users}
            onRemoveUser={handleRemoveUser}
            onAddUser={handleAddUserAdmin}
            onToggleAdmin={handleToggleAdmin}
          />
        )}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white/90 backdrop-blur-xl border-t border-slate-100 h-16 flex items-center justify-around px-2 pb-2 z-50">
        <button onClick={() => setActiveView('dashboard')} className={`flex flex-col items-center gap-1 flex-1 transition-all ${activeView === 'dashboard' ? 'text-indigo-600' : 'text-slate-400'}`}>
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" />
          </svg>
          <span className="text-[9px] font-bold uppercase tracking-wider">Inicio</span>
        </button>
        <button onClick={() => setActiveView('leaderboard')} className={`flex flex-col items-center gap-1 flex-1 transition-all ${activeView === 'leaderboard' ? 'text-indigo-600' : 'text-slate-400'}`}>
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
          </svg>
          <span className="text-[9px] font-bold uppercase tracking-wider">Ranking</span>
        </button>
        <button onClick={() => setActiveView('rules')} className={`flex flex-col items-center gap-1 flex-1 transition-all ${activeView === 'rules' ? 'text-indigo-600' : 'text-slate-400'}`}>
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
          </svg>
          <span className="text-[9px] font-bold uppercase tracking-wider">Reglas</span>
        </button>
        {currentUser?.isAdmin && (
          <button onClick={() => setActiveView('admin')} className={`flex flex-col items-center gap-1 flex-1 transition-all ${activeView === 'admin' ? 'text-indigo-600' : 'text-slate-400'}`}>
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
            </svg>
            <span className="text-[9px] font-bold uppercase tracking-wider">Admin</span>
          </button>
        )}
      </nav>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { CompetitionConfig, User } from '../types';

interface AdminSettingsProps {
  config: CompetitionConfig;
  onUpdateConfig: (newConfig: CompetitionConfig) => void;
  users: User[];
  onRemoveUser: (userId: string) => void;
  onAddUser: (userData: { realName: string, pseudonym: string, initialWeight: number }) => void;
  onToggleAdmin: (userId: string) => void;
}

const AdminSettings: React.FC<AdminSettingsProps> = ({ config, onUpdateConfig, users, onRemoveUser, onAddUser, onToggleAdmin }) => {
  const [formData, setFormData] = useState<CompetitionConfig>(config);
  const [userToDelete, setUserToDelete] = useState<User | null>(null);
  const [showAddForm, setShowAddForm] = useState(false);

  const [newUser, setNewUser] = useState({
    realName: '',
    pseudonym: '',
    initialWeight: ''
  });

  const handleSubmitConfig = (e: React.FormEvent) => {
    e.preventDefault();
    onUpdateConfig(formData);
    alert('Configuración actualizada correctamente');
  };

  const handleAddUserSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const weight = parseFloat(newUser.initialWeight);
    if (newUser.realName && newUser.pseudonym && !isNaN(weight)) {
      onAddUser({
        realName: newUser.realName,
        pseudonym: newUser.pseudonym,
        initialWeight: weight
      });
      setNewUser({ realName: '', pseudonym: '', initialWeight: '' });
      setShowAddForm(false);
      alert('Participante añadido con éxito');
    }
  };

  const confirmDelete = () => {
    if (userToDelete) {
      onRemoveUser(userToDelete.id);
      setUserToDelete(null);
    }
  };

  return (
    <div className="space-y-6 pb-20 px-2 relative">
      <div>
        <h2 className="text-2xl font-bold text-slate-800">Panel de Control</h2>
        <p className="text-sm text-slate-500">Gestión del periodo y participantes</p>
