      <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-100 space-y-4">
        <div className="flex justify-between items-center border-b pb-2 mb-2">
          <h3 className="text-sm font-bold text-slate-800">Participantes</h3>
          <button 
            onClick={() => setShowAddForm(!showAddForm)}
            className="text-xs bg-indigo-100 text-indigo-700 font-bold px-3 py-1.5 rounded-lg hover:bg-indigo-200 transition-colors"
          >
            {showAddForm ? 'Cancelar' : '+ Añadir'}
