import React, { useEffect, useState } from 'react';
import { User, WeighIn, CompetitionConfig } from '../types';
import { ResponsiveContainer, Tooltip, AreaChart, Area } from 'recharts';
import { getMotivationalMessage } from '../services/geminiService';

interface DashboardProps {
  user: User;
  leaderboard: User[];
  onAddWeight: (weight: number, ateOut: boolean) => void;
  config: CompetitionConfig;
}

const Dashboard: React.FC<DashboardProps> = ({ user, leaderboard, onAddWeight, config }) => {
  const [newWeight, setNewWeight] = useState('');
  const [ateOut, setAteOut] = useState(false);
  const [aiMessage, setAiMessage] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  const fetchMessage = async () => {
    setLoadingAi(true);
    const msg = await getMotivationalMessage(user, leaderboard);
    setAiMessage(msg || null);
    setLoadingAi(false);
  };

  useEffect(() => {
    fetchMessage();
  }, [user.id, leaderboard.length]);

  const today = new Date().toISOString().split('T')[0];
  const hasRegisteredToday = user.history.some(h => h.date === today);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (hasRegisteredToday) return;

    const weight = parseFloat(newWeight);
    if (!isNaN(weight) && weight > 0) {
      onAddWeight(weight, ateOut);
      setNewWeight('');
      setAteOut(false);
    }
  };

  const getProgress = () => {
    const start = new Date(config.startDate).getTime();
    const end = new Date(config.endDate).getTime();
    const now = new Date().getTime();
    const total = end - start;
    const elapsed = now - start;
    return Math.min(Math.max((elapsed / total) * 100, 0), 100);
  };

  const chartData = user.history.map((h, index) => {
    let accumulated = 0;
    for(let i=0; i<=index; i++) accumulated += user.history[i].delta;
    return {
      name: `S${index}`,
      pérdida: Math.abs(accumulated).toFixed(1),
      puntos: h.points
    };
  });

  return (
    <div className="space-y-6 pb-20">
      <div className="bg-gradient-to-br from-indigo-500 to-purple-600 rounded-3xl p-6 text-white shadow-xl relative overflow-hidden">
        <div className="relative z-10">
          <div className="flex justify-between items-center mb-1">
            <p className="text-indigo-100 text-sm font-medium">Tu progreso hoy</p>
            <div className="flex items-center gap-2">
               <button 
                onClick={fetchMessage}
                disabled={loadingAi}
                className={`p-1.5 bg-white/10 rounded-full hover:bg-white/20 transition-all ${loadingAi ? 'animate-spin opacity-50' : ''}`}
                title="Nuevo mensaje del coach"
               >
                 <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                 </svg>
               </button>
               <p className="text-[10px] text-white/60 font-bold uppercase tracking-widest">
                Reto: {Math.round(getProgress())}%
              </p>
            </div>
          </div>
          <div className="w-full h-1 bg-white/10 rounded-full mb-4 overflow-hidden">
            <div 
              className="h-full bg-amber-400 transition-all duration-1000" 
              style={{ width: `${getProgress()}%` }}
            ></div>
          </div>

          <div className="min-h-[4rem] flex items-center">
            {loadingAi ? (
              <div className="flex gap-1">
                <div className="w-2 h-2 bg-white/40 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-white/40 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                <div className="w-2 h-2 bg-white/40 rounded-full animate-bounce [animation-delay:0.4s]"></div>
              </div>
            ) : (
              <h2 className="text-xl font-bold italic leading-tight animate-in fade-in slide-in-from-left-4 duration-500">
                {aiMessage}
              </h2>
            )}
          </div>

          <div className="grid grid-cols-2 gap-4 mt-4">
            <div className="bg-white/10 backdrop-blur-md rounded-2xl p-3 border border-white/5">
