            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
          </svg>
          Registro Diario
        </h3>

        {hasRegisteredToday ? (
          <div className="bg-emerald-50 border border-emerald-100 rounded-3xl p-6 text-center animate-in zoom-in-95 duration-300">
            <div className="w-16 h-16 bg-emerald-500 rounded-full flex items-center justify-center text-white text-2xl mx-auto mb-4 shadow-lg shadow-emerald-100">
              ✓
            </div>
            <p className="text-emerald-800 font-bold text-lg mb-1">¡Peso guardado!</p>
            <p className="text-emerald-600 text-sm">Ya has cumplido con tu registro hoy. ¡Vuelve mañana para seguir sumando!</p>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="flex gap-2">
              <div className="relative flex-1">
                <input 
                  type="number" 
                  step="0.1"
                  value={newWeight}
                  onChange={(e) => setNewWeight(e.target.value)}
                  placeholder="Tu peso hoy..."
                  className="w-full bg-slate-50 border-none rounded-2xl py-3.5 px-5 text-slate-700 font-medium focus:ring-2 focus:ring-indigo-500 transition-all outline-none"
                />
