          <div className="bg-emerald-50 border border-emerald-100 rounded-3xl p-6 text-center animate-in zoom-in-95 duration-300">
            <div className="w-16 h-16 bg-emerald-500 rounded-full flex items-center justify-center text-white text-2xl mx-auto mb-4 shadow-lg shadow-emerald-100">
              ✓
            </div>
            <p className="text-emerald-800 font-bold text-lg mb-1">¡Peso guardado!</p>
            <p className="text-emerald-600 text-sm">Ya has cumplido con tu registro hoy. ¡Vuelve mañana para seguir sumando!</p>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="flex gap-2">
              <div className="relative flex-1">
                <input 
                  type="number" 
                  step="0.1"
                  value={newWeight}
                  onChange={(e) => setNewWeight(e.target.value)}
                  placeholder="Tu peso hoy..."
                  className="w-full bg-slate-50 border-none rounded-2xl py-3.5 px-5 text-slate-700 font-medium focus:ring-2 focus:ring-indigo-500 transition-all outline-none"
                />
                <span className="absolute right-4 top-3.5 text-slate-400 font-bold">kg</span>
              </div>
              <button 
                type="submit"
                className="bg-indigo-600 text-white font-bold py-3.5 px-6 rounded-2xl hover:bg-indigo-700 active:scale-95 transition-all shadow-lg shadow-indigo-100"
              >
                Enviar
              </button>
            </div>

            <label className="flex items-center gap-3 p-4 bg-slate-50 rounded-2xl cursor-pointer select-none active:bg-slate-100 transition-colors border border-transparent active:border-slate-200">
              <input 
                type="checkbox" 
                checked={ateOut}
                onChange={(e) => setAteOut(e.target.checked)}
                className="w-5 h-5 rounded-lg border-slate-300 text-indigo-600 focus:ring-indigo-500"
              />
              <div className="flex-1">
                <p className="text-sm font-bold text-slate-700">¿Comiste fuera ayer?</p>
                <p className="text-[10px] text-indigo-500 uppercase font-bold tracking-tight">¡Bono Social de +50 pts!</p>
              </div>
              <span className="text-2xl">🍽️</span>
            </label>
          </form>
        )}
      </div>

      {/* Historial de Registros */}
      <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
          <svg className="w-5 h-5 text-indigo-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
          Historial de Pesajes
        </h3>

        {user.history.length === 0 ? (
          <p className="text-center text-slate-400 py-8 text-sm italic">Aún no has registrado ningún peso. ¡Tu cambio empieza hoy!</p>
        ) : (
          <div className="space-y-3">
            {[...user.history].reverse().map((entry) => (
              <div key={entry.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100 transition-all hover:bg-slate-100/50">
                <div className="flex items-center gap-3">
                  <div className="bg-white w-10 h-10 rounded-xl flex flex-col items-center justify-center shadow-sm border border-slate-100">
                    <span className="text-[10px] font-black uppercase text-indigo-600 leading-none">{formatDate(entry.date).split(' ')[1]}</span>
                    <span className="text-sm font-bold text-slate-800 leading-tight">{formatDate(entry.date).split(' ')[0]}</span>
                  </div>
                  <div>
                    <p className="text-sm font-black text-slate-800">{entry.weight.toFixed(1)} kg</p>
                    <p className={`text-[10px] font-bold uppercase ${entry.delta <= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                      {entry.delta > 0 ? '+' : ''}{entry.delta.toFixed(1)} kg {entry.ateOut ? ' • 🍽️' : ''}
                    </p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-sm font-black text-indigo-600">+{entry.points}</p>
                  <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Puntos</p>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { User, WeighIn, CompetitionConfig } from './types';
import { MOCK_USERS, INITIAL_RULES, COMPETITION_CONFIG } from './constants';
import TopNav from './components/TopNav';
import Dashboard from './components/Dashboard';
import Leaderboard from './components/Leaderboard';
import Rules from './components/Rules';
import AdminSettings from './components/AdminSettings';
import LandingPage from './components/LandingPage';

type View = 'dashboard' | 'leaderboard' | 'rules' | 'admin' | 'welcome';

const App: React.FC = () => {
  const [users, setUsers] = useState<User[]>(MOCK_USERS);
  const [currentUserId, setCurrentUserId] = useState<string | null>(users[0]?.id || null); 
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [competitionConfig, setCompetitionConfig] = useState<CompetitionConfig>(COMPETITION_CONFIG);

  const currentUser = users.find(u => u.id === currentUserId) || null;

  // Función para obtener la fecha local en formato YYYY-MM-DD
  const getLocalDate = () => {
    const d = new Date();
    const offset = d.getTimezoneOffset();
    const localDate = new Date(d.getTime() - (offset * 60 * 1000));
    return localDate.toISOString().split('T')[0];
  };

  const handleAddWeight = (weight: number, ateOut: boolean) => {
    if (!currentUser) return;

    const today = getLocalDate();
    const alreadyRegistered = currentUser.history.some(h => h.date === today);

    if (alreadyRegistered) {
      alert("Ya has registrado tu peso hoy. ¡Vuelve mañana!");
      return;
    }

    const lastWeighIn = currentUser.history.length > 0 
      ? currentUser.history[currentUser.history.length - 1] 
      : { weight: currentUser.initialWeight };

    const delta = weight - lastWeighIn.weight;

    let earnedPoints = 10; 
    if (delta < 0) {
      earnedPoints += Math.floor(Math.abs(delta) * 100); 
    } else if (delta > 0) {
      earnedPoints -= Math.floor(delta * 150); 
    }
    if (ateOut) earnedPoints += 50;

    const newWeighIn: WeighIn = {
      id: Math.random().toString(36).substr(2, 9),
      date: today,
      weight: weight,
      delta: delta,
      points: earnedPoints,
      ateOut: ateOut
    };

    const updatedUser = {
      ...currentUser,
      history: [...currentUser.history, newWeighIn],
      totalPoints: Math.max(0, currentUser.totalPoints + earnedPoints),
      totalWeightLoss: currentUser.initialWeight - weight
    };

    setUsers(prev => prev.map(u => u.id === currentUser.id ? updatedUser : u));
    alert(`¡Peso registrado! Has obtenido ${earnedPoints} puntos.`);
  };

  const handleRemoveUser = (userId: string) => {
    if (userId === currentUserId) {
      alert("No puedes eliminarte a ti mismo.");
      return;
    }
    setUsers(prev => prev.filter(u => u.id !== userId));
  };

  const handleToggleAdmin = (userId: string) => {
    if (userId === currentUserId) {
      alert("No puedes quitarte el permiso de admin a ti mismo.");
      return;
    }
    setUsers(prev => prev.map(u => u.id === userId ? { ...u, isAdmin: !u.isAdmin } : u));
  };

  const handleRegister = (userData: { realName: string, pseudonym: string, initialWeight: number }) => {
    const newId = Math.random().toString(36).substr(2, 9);
    const newUser: User = {
      id: newId,
      realName: userData.realName,
      pseudonym: userData.pseudonym,
      initialWeight: userData.initialWeight,
      avatar: `https://picsum.photos/seed/${userData.pseudonym}/200`,
      history: [],
      totalPoints: 0,
      totalWeightLoss: 0,
      isAdmin: users.length === 0 
    };

    setUsers(prev => [...prev, newUser]);
    setCurrentUserId(newId);
    setActiveView('dashboard');
  };

  const handleAddUserAdmin = (userData: { realName: string, pseudonym: string, initialWeight: number }) => {
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      realName: userData.realName,
      pseudonym: userData.pseudonym,
      initialWeight: userData.initialWeight,
      avatar: `https://picsum.photos/seed/${userData.pseudonym}/200`,
      history: [],
      totalPoints: 0,
      totalWeightLoss: 0,
      isAdmin: false
    };
    setUsers(prev => [...prev, newUser]);
  };

  const handleLogout = () => {
    if (users.length > 1) {
      const currentIndex = users.findIndex(u => u.id === currentUserId);
      const nextUserIndex = (currentIndex + 1) % users.length;
      setCurrentUserId(users[nextUserIndex].id);
      setActiveView('dashboard');
    } else {
      setCurrentUserId(null);
      setActiveView('welcome');
    }
  };

  if (!currentUserId || !currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 max-w-md mx-auto shadow-2xl relative flex flex-col">
        <TopNav currentUser={null} onLogout={() => {}} />
        <main className="flex-1 p-4 overflow-y-auto">
          <LandingPage onRegister={handleRegister} />
        </main>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 max-w-md mx-auto shadow-2xl relative flex flex-col">
      <TopNav currentUser={currentUser} onLogout={handleLogout} />

      <main className="flex-1 p-4 overflow-y-auto">
        {activeView === 'dashboard' && (
          <Dashboard 
            user={currentUser} 
            leaderboard={users} 
            onAddWeight={handleAddWeight} 
            config={competitionConfig}
          />
        )}
        {activeView === 'leaderboard' && (
          <Leaderboard users={users} currentUser={currentUser} config={competitionConfig} />
        )}
        {activeView === 'rules' && (
          <Rules rules={INITIAL_RULES} />
        )}
        {activeView === 'admin' && currentUser.isAdmin && (
          <AdminSettings 
            config={competitionConfig} 
            onUpdateConfig={setCompetitionConfig} 
            users={users}
            onRemoveUser={handleRemoveUser}
            onAddUser={handleAddUserAdmin}
            onToggleAdmin={handleToggleAdmin}
          />
        )}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white/90 backdrop-blur-xl border-t border-slate-100 h-16 flex items-center justify-around px-2 pb-2 z-50">
        <button onClick={() => setActiveView('dashboard')} className={`flex flex-col items-center gap-1 flex-1 transition-all ${activeView === 'dashboard' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" />
          </svg>
          <span className="text-[9px] font-bold uppercase tracking-wider">Inicio</span>
        </button>
        <button onClick={() => setActiveView('leaderboard')} className={`flex flex-col items-center gap-1 flex-1 transition-all ${activeView === 'leaderboard' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
          </svg>
          <span className="text-[9px] font-bold uppercase tracking-wider">Ranking</span>
        </button>
        <button onClick={() => setActiveView('rules')} className={`flex flex-col items-center gap-1 flex-1 transition-all ${activeView === 'rules' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
          </svg>
          <span className="text-[9px] font-bold uppercase tracking-wider">Reglas</span>
        </button>
        {currentUser.isAdmin && (
          <button onClick={() => setActiveView('admin')} className={`flex flex-col items-center gap-1 flex-1 transition-all ${activeView === 'admin' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
            </svg>
            <span className="text-[9px] font-bold uppercase tracking-wider">Admin</span>
          </button>
        )}
      </nav>
    </div>
  );
};

export default App;

import React, { useEffect, useState } from 'react';
import { User, WeighIn, CompetitionConfig } from '../types';
import { ResponsiveContainer, Tooltip, AreaChart, Area } from 'recharts';
import { getMotivationalMessage } from '../services/geminiService';

interface DashboardProps {
  user: User;
  leaderboard: User[];
  onAddWeight: (weight: number, ateOut: boolean) => void;
  config: CompetitionConfig;
}

const Dashboard: React.FC<DashboardProps> = ({ user, leaderboard, onAddWeight, config }) => {
  const [newWeight, setNewWeight] = useState('');
  const [ateOut, setAteOut] = useState(false);
  const [aiMessage, setAiMessage] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  const fetchMessage = async () => {
    setLoadingAi(true);
    const msg = await getMotivationalMessage(user, leaderboard);
    setAiMessage(msg || null);
    setLoadingAi(false);
  };

  useEffect(() => {
    fetchMessage();
  }, [user.id, leaderboard.length]);

  // Función para obtener la fecha local en formato YYYY-MM-DD
  const getLocalDate = () => {
    const d = new Date();
    const offset = d.getTimezoneOffset();
    const localDate = new Date(d.getTime() - (offset * 60 * 1000));
    return localDate.toISOString().split('T')[0];
  };

  const today = getLocalDate();
  const hasRegisteredToday = user.history.some(h => h.date === today);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (hasRegisteredToday) return;

    const weight = parseFloat(newWeight);
    if (!isNaN(weight) && weight > 0) {
      onAddWeight(weight, ateOut);
      setNewWeight('');
      setAteOut(false);
    }
  };

  const getProgress = () => {
    const start = new Date(config.startDate).getTime();
    const end = new Date(config.endDate).getTime();
    const now = new Date().getTime();
    const total = end - start;
    const elapsed = now - start;
    return Math.min(Math.max((elapsed / total) * 100, 0), 100);
  };

  const chartData = user.history.map((h, index) => {
    let accumulated = 0;
    for(let i=0; i<=index; i++) accumulated += user.history[i].delta;
    return {
      name: `S${index}`,
      pérdida: Math.abs(accumulated).toFixed(1),
      puntos: h.points
    };
  });

  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr);
    return date.toLocaleDateString('es-ES', { day: 'numeric', month: 'short' });
  };

  return (
    <div className="space-y-6 pb-24">
      {/* Banner Motivacional IA */}
      <div className="bg-gradient-to-br from-indigo-500 to-purple-600 rounded-3xl p-6 text-white shadow-xl relative overflow-hidden">
        <div className="relative z-10">
          <div className="flex justify-between items-center mb-1">
            <p className="text-indigo-100 text-sm font-medium">Tu progreso hoy</p>
            <div className="flex items-center gap-2">
               <button 
                onClick={fetchMessage}
                disabled={loadingAi}
                className={`p-1.5 bg-white/10 rounded-full hover:bg-white/20 transition-all ${loadingAi ? 'animate-spin opacity-50' : ''}`}
                title="Nuevo mensaje del coach"
               >
                 <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                 </svg>
               </button>
               <p className="text-[10px] text-white/60 font-bold uppercase tracking-widest">
                Reto: {Math.round(getProgress())}%
              </p>
            </div>
          </div>
          <div className="w-full h-1 bg-white/10 rounded-full mb-4 overflow-hidden">
            <div 
              className="h-full bg-amber-400 transition-all duration-1000" 
              style={{ width: `${getProgress()}%` }}
            ></div>
          </div>

          <div className="min-h-[4rem] flex items-center">
            {loadingAi ? (
              <div className="flex gap-1">
                <div className="w-2 h-2 bg-white/40 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-white/40 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                <div className="w-2 h-2 bg-white/40 rounded-full animate-bounce [animation-delay:0.4s]"></div>
              </div>
            ) : (
              <h2 className="text-xl font-bold italic leading-tight animate-in fade-in slide-in-from-left-4 duration-500">
                {aiMessage}
              </h2>
            )}
          </div>

          <div className="grid grid-cols-2 gap-4 mt-4">
            <div className="bg-white/10 backdrop-blur-md rounded-2xl p-3 border border-white/5">
              <p className="text-[10px] text-indigo-100 uppercase font-bold">Puntos Totales</p>
              <p className="text-xl font-bold">{user.totalPoints} pts</p>
            </div>
            <div className="bg-white/10 backdrop-blur-md rounded-2xl p-3 border border-white/5">
              <p className="text-[10px] text-indigo-100 uppercase font-bold">Pérdida Total</p>
              <p className="text-xl font-bold">{user.totalWeightLoss.toFixed(1)} kg</p>
            </div>
          </div>
        </div>
        <div className="absolute top-[-20%] right-[-10%] w-40 h-40 bg-white/10 rounded-full blur-3xl"></div>
      </div>

      {/* Gráfico de Evolución */}
      <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
          <svg className="w-5 h-5 text-indigo-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" />
          </svg>
          Curva de Esfuerzo
        </h3>
        <div className="h-48 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={chartData}>
              <defs>
                <linearGradient id="colorLoss" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3}/>
                  <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                </linearGradient>
              </defs>
              <Tooltip 
                contentStyle={{ borderRadius: '20px', border: 'none', boxShadow: '0 10px 25px -5px rgba(0,0,0,0.1)', fontSize: '12px' }}
                itemStyle={{ fontWeight: 'bold', color: '#6366f1' }}
              />
              <Area type="monotone" dataKey="pérdida" stroke="#6366f1" strokeWidth={4} fillOpacity={1} fill="url(#colorLoss)" />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Formulario de Registro */}
      <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
           <svg className="w-5 h-5 text-indigo-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
          </svg>
          Registro Diario
        </h3>

        {hasRegisteredToday ? (
          <div className="bg-emerald-50 border border-emerald-100 rounded-3xl p-6 text-center animate-in zoom-in-95 duration-300">
            <div className="w-16 h-16 bg-emerald-500 rounded-full flex items-center justify-center text-white text-2xl mx-auto mb-4 shadow-lg shadow-emerald-100">
              ✓
            </div>
            <p className="text-emerald-800 font-bold text-lg mb-1">¡Peso guardado!</p>
            <p className="text-emerald-600 text-sm">Ya has cumplido con tu registro hoy. ¡Vuelve mañana para seguir sumando!</p>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="flex gap-2">
              <div className="relative flex-1">
                <input 
                  type="number" 
                  step="0.1"
                  value={newWeight}
                  onChange={(e) => setNewWeight(e.target.value)}
                  placeholder="Tu peso hoy..."
                  className="w-full bg-slate-50 border-none rounded-2xl py-3.5 px-5 text-slate-700 font-medium focus:ring-2 focus:ring-indigo-500 transition-all outline-none"
                />
                <span className="absolute right-4 top-3.5 text-slate-400 font-bold">kg</span>
              </div>
              <button 
                type="submit"
                className="bg-indigo-600 text-white font-bold py-3.5 px-6 rounded-2xl hover:bg-indigo-700 active:scale-95 transition-all shadow-lg shadow-indigo-100"
              >
                Enviar
              </button>
            </div>

            <label className="flex items-center gap-3 p-4 bg-slate-50 rounded-2xl cursor-pointer select-none active:bg-slate-100 transition-colors border border-transparent active:border-slate-200">
              <input 
                type="checkbox" 
                checked={ateOut}
                onChange={(e) => setAteOut(e.target.checked)}
                className="w-5 h-5 rounded-lg border-slate-300 text-indigo-600 focus:ring-indigo-500"
              />
