import React, { useEffect, useState } from 'react';
import { User, WeighIn, CompetitionConfig } from '../types';
import { ResponsiveContainer, Tooltip, AreaChart, Area } from 'recharts';
import { getMotivationalMessage } from '../services/geminiService';

interface DashboardProps {
  user: User;
  leaderboard: User[];
  onAddWeight: (weight: number, ateOut: boolean) => void;
  config: CompetitionConfig;
}

const Dashboard: React.FC<DashboardProps> = ({ user, leaderboard, onAddWeight, config }) => {
  const [newWeight, setNewWeight] = useState('');
  const [ateOut, setAteOut] = useState(false);
  const [aiMessage, setAiMessage] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  const fetchMessage = async () => {
    setLoadingAi(true);
    const msg = await getMotivationalMessage(user, leaderboard);
    setAiMessage(msg || null);
    setLoadingAi(false);
  };

  useEffect(() => {
    fetchMessage();
  }, [user.id, leaderboard.length]);

  // Función para obtener la fecha local en formato YYYY-MM-DD
  const getLocalDate = () => {
    const d = new Date();
    const offset = d.getTimezoneOffset();
    const localDate = new Date(d.getTime() - (offset * 60 * 1000));
    return localDate.toISOString().split('T')[0];
  };

  const today = getLocalDate();
  const hasRegisteredToday = user.history.some(h => h.date === today);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (hasRegisteredToday) return;

    const weight = parseFloat(newWeight);
    if (!isNaN(weight) && weight > 0) {
      onAddWeight(weight, ateOut);
      setNewWeight('');
      setAteOut(false);
    }
  };

  const getProgress = () => {
    const start = new Date(config.startDate).getTime();
    const end = new Date(config.endDate).getTime();
    const now = new Date().getTime();
    const total = end - start;
    const elapsed = now - start;
    return Math.min(Math.max((elapsed / total) * 100, 0), 100);
  };

  const chartData = user.history.map((h, index) => {
    let accumulated = 0;
    for(let i=0; i<=index; i++) accumulated += user.history[i].delta;
    return {
      name: `S${index}`,
      pérdida: Math.abs(accumulated).toFixed(1),
      puntos: h.points
    };
  });

