                  <p className={`text-[10px] font-bold uppercase ${entry.delta <= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {entry.delta > 0 ? '+' : ''}{entry.delta.toFixed(1)} kg {entry.ateOut ? ' • 🍽️' : ''}
