              </div>
            </div>
            <div className="text-right opacity-40">
              <p className="text-sm font-black text-slate-400">0</p>
              <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Puntos</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

