    return saved ? JSON.parse(saved) : COMPETITION_CONFIG;
  });

  const currentUser = users.find(u => u.id === currentUserId) || null;

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_USERS, JSON.stringify(users));
  }, [users]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_CONFIG, JSON.stringify(competitionConfig));
  }, [competitionConfig]);

  const getLocalDate = (date = new Date()) => {
    const offset = date.getTimezoneOffset();
    const localDate = new Date(date.getTime() - (offset * 60 * 1000));
    return localDate.toISOString().split('T')[0];
  };

  const handleAddWeight = (weight: number, ateOut: boolean) => {
    if (!currentUser) return;

    const now = new Date();
    const todayStr = getLocalDate(now);
    const alreadyRegistered = currentUser.history.some(h => h.date === todayStr);

    if (alreadyRegistered) {
      alert("Ya has registrado tu peso hoy. ¡Vuelve mañana!");
      return;
    }

    const lastWeighIn = currentUser.history.length > 0 
      ? currentUser.history[currentUser.history.length - 1] 
      : { weight: currentUser.initialWeight, delta: 0, date: competitionConfig.startDate };

    const delta = weight - lastWeighIn.weight;

    // 1. Puntos base por registro diario
    let earnedPoints = 10; 
    let messages: string[] = [];

    // 2. Lógica de Peso (Pérdida / Mantenimiento / Ganancia)
    if (delta <= -0.11) {
      // Pérdida: +10 pts por cada 100g
      earnedPoints += Math.floor(Math.abs(delta) * 100); 
    } else if (delta > 0.1) {
      // Ganancia: -15 pts por cada 100g
      earnedPoints -= Math.floor(delta * 150); 
    } else {
      // Regla MANTENIMIENTO: ±100g (+5 pts)
      earnedPoints += 5;
      messages.push("⚖️ ¡Bono Mantenimiento! Mantenerse es mejor que subir. (+5 pts)");
    }

    // 3. Bono Social (+50 pts)
    if (ateOut) {
      earnedPoints += 50;
      messages.push("🍽️ ¡Bono Social! Disfrutar fuera también puntúa. (+50 pts)");
    }

    // 4. Regla MADRUGADOR (Antes de las 10:00 AM) (+5 pts)
    if (now.getHours() < 10) {
      earnedPoints += 5;
      messages.push("🌅 ¡Bono Madrugador! Registro temprano completado. (+5 pts)");
    }

    // 5. Regla RACHA 3 DÍAS BAJANDO (+20 pts)
    if (delta < 0 && currentUser.history.length >= 2) {
      const last = currentUser.history[currentUser.history.length - 1];
      const secondLast = currentUser.history[currentUser.history.length - 2];
      if (last.delta < 0 && secondLast.delta < 0) {
        earnedPoints += 20;
        messages.push("🔥 ¡Racha de Éxito! 3 días seguidos perdiendo peso. (+20 pts)");
      }
    }

    // 6. Regla SÚPER CONSTANCIA (7 días consecutivos) (+50 pts)
    const checkSuperConsistency = () => {
      if (currentUser.history.length < 6) return false;

      const last6 = currentUser.history.slice(-6);
      const yesterday = new Date();
      yesterday.setDate(yesterday.getDate() - 1);
      const yesterdayStr = getLocalDate(yesterday);

      // El último registro debe ser de ayer
      if (last6[last6.length - 1].date !== yesterdayStr) return false;

      // Comprobar que no hay huecos en los últimos 6 días
      for (let i = 1; i < last6.length; i++) {
        const d1 = new Date(last6[i-1].date);
        const d2 = new Date(last6[i].date);
        const diffDays = Math.round((d2.getTime() - d1.getTime()) / (1000 * 3600 * 24));
        if (diffDays !== 1) return false;
      }
      return true;
    };

    if (checkSuperConsistency()) {
      earnedPoints += 50;
      messages.push("⭐ ¡SÚPER CONSTANCIA! 7 días seguidos registrando. (+50 pts)");
    }

    // 7. Lógica de Hitos por Kilo (+100 pts)
    const oldLoss = currentUser.totalWeightLoss;
    const newLoss = currentUser.initialWeight - weight;
    const crossedMilestone = Math.floor(newLoss) > Math.floor(oldLoss) && newLoss > 0;
    if (crossedMilestone) {
      earnedPoints += 100;
      messages.push(`🎉 ¡HITO! Has perdido un total de ${Math.floor(newLoss)}kg. (+100 pts)`);
    }

    const newWeighIn: WeighIn = {
      id: Math.random().toString(36).substr(2, 9),
      date: todayStr,
      weight: weight,
      delta: delta,
      points: earnedPoints,
      ateOut: ateOut
    };

    const updatedUser = {
      ...currentUser,
      history: [...currentUser.history, newWeighIn],
      totalPoints: Math.max(0, currentUser.totalPoints + earnedPoints),
      totalWeightLoss: newLoss
    };

    setUsers(prev => prev.map(u => u.id === currentUser.id ? updatedUser : u));

    alert(`¡Peso registrado!\n\nHas sumado ${earnedPoints} puntos.${messages.length > 0 ? '\n\n' + messages.join('\n') : ''}`);
  };

  const handleRemoveUser = (userId: string) => {
    if (userId === currentUserId) {
      alert("No puedes eliminarte a ti mismo.");
      return;
    }
    setUsers(prev => prev.filter(u => u.id !== userId));
  };

  const handleToggleAdmin = (userId: string) => {
    if (userId === currentUserId) {
      alert("No puedes quitarte el permiso de admin a ti mismo.");
      return;
    }
    setUsers(prev => prev.map(u => u.id === userId ? { ...u, isAdmin: !u.isAdmin } : u));
  };

  const handleRegister = (userData: { realName: string, pseudonym: string, initialWeight: number }) => {
    const newId = Math.random().toString(36).substr(2, 9);
    const newUser: User = {
      id: newId,
      realName: userData.realName,
      pseudonym: userData.pseudonym,
      initialWeight: userData.initialWeight,
      avatar: `https://picsum.photos/seed/${userData.pseudonym}/200`,
      history: [],
      totalPoints: 0,
      totalWeightLoss: 0,
      isAdmin: users.length === 0 
    };

    setUsers(prev => [...prev, newUser]);
    setCurrentUserId(newId);
    setActiveView('dashboard');
  };

  const handleAddUserAdmin = (userData: { realName: string, pseudonym: string, initialWeight: number }) => {
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      realName: userData.realName,
      pseudonym: userData.pseudonym,
      initialWeight: userData.initialWeight,
      avatar: `https://picsum.photos/seed/${userData.pseudonym}/200`,
      history: [],
      totalPoints: 0,
      totalWeightLoss: 0,
      isAdmin: false
    };
    setUsers(prev => [...prev, newUser]);
  };

  const handleLogout = () => {
    if (users.length > 1) {
      const currentIndex = users.findIndex(u => u.id === currentUserId);
      const nextUserIndex = (currentIndex + 1) % users.length;
      setCurrentUserId(users[nextUserIndex].id);
      setActiveView('dashboard');
    } else {
      setCurrentUserId(null);
      setActiveView('welcome');
    }
  };

  if (!currentUserId || !currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 max-w-md mx-auto shadow-2xl relative flex flex-col">
        <TopNav currentUser={null} onLogout={() => {}} />
        <main className="flex-1 p-4 overflow-y-auto">
          <LandingPage onRegister={handleRegister} />
        </main>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 max-w-md mx-auto shadow-2xl relative flex flex-col">
      <TopNav currentUser={currentUser} onLogout={handleLogout} />

      <main className="flex-1 p-4 overflow-y-auto">
        {activeView === 'dashboard' && (
          <Dashboard 
            user={currentUser} 
            leaderboard={users} 
            onAddWeight={handleAddWeight} 
            config={competitionConfig}
          />
        )}
        {activeView === 'leaderboard' && (
          <Leaderboard users={users} currentUser={currentUser} config={competitionConfig} />
        )}
        {activeView === 'rules' && (
          <Rules rules={INITIAL_RULES} />
        )}
        {activeView === 'admin' && currentUser.isAdmin && (
          <AdminSettings 
            config={competitionConfig} 
            onUpdateConfig={setCompetitionConfig} 
            users={users}
            onRemoveUser={handleRemoveUser}
            onAddUser={handleAddUserAdmin}
            onToggleAdmin={handleToggleAdmin}
          />
        )}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-white/90 backdrop-blur-xl border-t border-slate-100 h-16 flex items-center justify-around px-2 pb-2 z-50">
        <button onClick={() => setActiveView('dashboard')} className={`flex flex-col items-center gap-1 flex-1 transition-all ${activeView === 'dashboard' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" />
          </svg>
          <span className="text-[9px] font-bold uppercase tracking-wider">Inicio</span>
        </button>
        <button onClick={() => setActiveView('leaderboard')} className={`flex flex-col items-center gap-1 flex-1 transition-all ${activeView === 'leaderboard' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
          </svg>
          <span className="text-[9px] font-bold uppercase tracking-wider">Ranking</span>
        </button>
        <button onClick={() => setActiveView('rules')} className={`flex flex-col items-center gap-1 flex-1 transition-all ${activeView === 'rules' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
