      id: Math.random().toString(36).substr(2, 9),
      date: todayStr,
      weight: weight,
      delta: delta,
      points: earnedPoints,
      ateOut: ateOut
    };

    const updatedUser = {
      ...currentUser,
      history: [...currentUser.history, newWeighIn],
      totalPoints: Math.max(0, currentUser.totalPoints + earnedPoints),
      totalWeightLoss: newLoss
    };

    setUsers(prev => prev.map(u => u.id === currentUser.id ? updatedUser : u));
    alert(`¡Peso registrado!\n\nHas sumado ${earnedPoints} puntos.${messages.length > 0 ? '\n\n' + messages.join('\n') : ''}`);
  };

  const handleRemoveUser = (userId: string) => {
    if (userId === currentUserId) {
      alert("No puedes eliminarte a ti mismo.");
      return;
    }
    setUsers(prev => prev.filter(u => u.id !== userId));
  };

  const handleToggleAdmin = (userId: string) => {
    if (userId === currentUserId) {
      alert("No puedes quitarte el permiso de admin a ti mismo.");
      return;
    }
    setUsers(prev => prev.map(u => u.id === userId ? { ...u, isAdmin: !u.isAdmin } : u));
  };

  const getRandomFruitAvatar = () => {
    const fruit = FRUITS[Math.floor(Math.random() * FRUITS.length)];
    const lock = Math.floor(Math.random() * 1000);
    return `https://loremflickr.com/200/200/${fruit}?lock=${lock}`;
  };

  const handleRegister = (userData: { realName: string, pseudonym: string, initialWeight: number }) => {
    const newId = Math.random().toString(36).substr(2, 9);
    const newUser: User = {
      id: newId,
      realName: userData.realName,
      pseudonym: userData.pseudonym,
      initialWeight: userData.initialWeight,
      avatar: getRandomFruitAvatar(),
      history: [],
      totalPoints: 0,
      totalWeightLoss: 0,
      isAdmin: users.length === 0 
    };
    setUsers(prev => [...prev, newUser]);
    setCurrentUserId(newId);
    setActiveView('dashboard');
  };

  const handleAddUserAdmin = (userData: { realName: string, pseudonym: string, initialWeight: number }) => {
    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      realName: userData.realName,
      pseudonym: userData.pseudonym,
      initialWeight: userData.initialWeight,
      avatar: getRandomFruitAvatar(),
      history: [],
      totalPoints: 0,
      totalWeightLoss: 0,
      isAdmin: false
    };
    setUsers(prev => [...prev, newUser]);
  };

  const handleLogout = () => {
    if (users.length > 1) {
      const currentIndex = users.findIndex(u => u.id === currentUserId);
      const nextUserIndex = (currentIndex + 1) % users.length;
      setCurrentUserId(users[nextUserIndex].id);
      setActiveView('dashboard');
    } else {
      setCurrentUserId(null);
      setActiveView('welcome');
    }
  };

  if (!currentUserId || !currentUser) {
    return (
      <div className="min-h-screen bg-slate-50 max-w-md mx-auto shadow-2xl relative flex flex-col">
        <TopNav currentUser={null} onLogout={() => {}} />
        <main className="flex-1 p-4 overflow-y-auto">
          <LandingPage onRegister={handleRegister} />
        </main>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 max-w-md mx-auto shadow-2xl relative flex flex-col">
      <TopNav currentUser={currentUser} onLogout={handleLogout} />
      <main className="flex-1 p-4 overflow-y-auto">
        {activeView === 'dashboard' && (
          <Dashboard user={currentUser} leaderboard={users} onAddWeight={handleAddWeight} config={competitionConfig} />
        )}
        {activeView === 'leaderboard' && (
          <Leaderboard users={users} currentUser={currentUser} config={competitionConfig} />
        )}
        {activeView === 'rules' && (
          <Rules rules={INITIAL_RULES} />
        )}
        {activeView === 'admin' && currentUser.isAdmin && (
          <AdminSettings 
            config={competitionConfig} onUpdateConfig={setCompetitionConfig} 
            users={users} onRemoveUser={handleRemoveUser} 
            onAddUser={handleAddUserAdmin} onToggleAdmin={handleToggleAdmin}
          />
