import React from 'react';
import { User, CompetitionConfig } from '../types';

interface LeaderboardProps {
  users: User[];
  currentUser: User | null;
  config: CompetitionConfig;
}

const Leaderboard: React.FC<LeaderboardProps> = ({ users, currentUser, config }) => {
  const sortedUsers = [...users].sort((a, b) => {
    if (b.totalPoints !== a.totalPoints) {
      return b.totalPoints - a.totalPoints;
    }
    const lossPctA = (a.totalWeightLoss / a.initialWeight) * 100;
    const lossPctB = (b.totalWeightLoss / b.initialWeight) * 100;
    return lossPctB - lossPctA;
  });

  const isAdmin = currentUser?.isAdmin;
  const isFinished = new Date().getTime() > new Date(config.endDate).getTime();

  const getDaysRemaining = () => {
    const end = new Date(config.endDate).getTime();
    const now = new Date().getTime();
    const diff = end - now;
    const days = Math.ceil(diff / (1000 * 60 * 60 * 24));

    if (days < 0) return "Finalizado";
    if (days === 0) return "Finaliza hoy";
    if (days === 1) return "Queda 1 día";
    return `Finaliza en ${days} días`;
  };

  const winner = sortedUsers[0];

  return (
    <div className="space-y-4 pb-24 px-2">
      <style>{`
        @keyframes shine {
          0% { background-position: -200% center; }
          100% { background-position: 200% center; }
        }
        .winner-card {
          background: linear-gradient(90deg, #fbbf24, #fef3c7, #fbbf24);
          background-size: 200% auto;
          animation: shine 3s linear infinite;
        }
      `}</style>

      <div className="flex justify-between items-end mb-6">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Ranking</h2>
          <p className="text-sm text-slate-500">{isFinished ? 'Resultados Finales' : '¿Quién lidera el cambio?'}</p>
        </div>
        <span className={`text-xs font-bold px-3 py-1 rounded-full uppercase tracking-tighter shadow-sm ${
          isFinished ? 'bg-indigo-600 text-white animate-pulse' : 'bg-amber-100 text-amber-700'
        }`}>
          {getDaysRemaining()}
        </span>
      </div>

      {isFinished && (
        <div className="winner-card p-6 rounded-[2.5rem] shadow-xl text-center mb-8 border-4 border-white transform hover:scale-[1.02] transition-transform">
          <div className="text-4xl mb-2">🏆</div>
          <h3 className="text-amber-900 font-black text-2xl uppercase tracking-tighter">¡Ganador Oficial!</h3>
          <div className="my-4 relative inline-block">
            <img 
              src={winner.avatar} 
              className="w-24 h-24 rounded-full border-4 border-white shadow-lg mx-auto"
              alt="Ganador"
            />
            <span className="absolute -bottom-2 -right-2 text-3xl">🥇</span>
          </div>
          <h4 className="text-xl font-bold text-amber-950">{winner.pseudonym}</h4>
          <p className="text-sm text-amber-900/70 font-bold uppercase">{winner.totalPoints} Puntos Totales</p>
        </div>
      )}

      <div className="space-y-3">
        {sortedUsers.map((user, index) => {
          const isTop3 = index < 3;
          const medals = ['🥇', '🥈', '🥉'];
          const lossPercentage = ((user.totalWeightLoss / user.initialWeight) * 100).toFixed(1);
          const isWinner = index === 0 && isFinished;

          return (
            <div 
              key={user.id}
              className={`flex items-center gap-4 p-4 rounded-3xl transition-all border ${
                index === 0 
                  ? isFinished ? 'bg-amber-50 border-amber-200' : 'bg-indigo-50 border-indigo-100 scale-105 shadow-md z-10' 
                  : 'bg-white border-slate-50 shadow-sm'
              } ${user.id === currentUser?.id ? 'border-indigo-300 ring-1 ring-indigo-100' : ''}`}
            >
              <div className="relative">
                <img 
                  src={user.avatar} 
                  alt={user.pseudonym} 
                  className="w-12 h-12 rounded-full object-cover border-2 border-white shadow-sm"
                />
                {isTop3 && (
                  <span className="absolute -top-2 -right-2 text-lg">
                    {medals[index]}
                  </span>
                )}
              </div>

              <div className="flex-1">
                <div className="flex items-center gap-2">
                  <h4 className="font-bold text-slate-800">{user.pseudonym}</h4>
                  {isAdmin && (
                    <span className="text-[10px] bg-slate-100 text-slate-400 px-1.5 py-0.5 rounded font-medium">
                      {user.realName}
                    </span>
                  )}
                </div>
                <div className="flex items-center gap-1">
                  <div className={`w-1.5 h-1.5 rounded-full ${user.totalWeightLoss >= 0 ? 'bg-emerald-500' : 'bg-rose-400'}`}></div>
                  <p className="text-[10px] text-slate-500 font-bold uppercase tracking-tight">
                    {user.totalWeightLoss.toFixed(1)}kg ({lossPercentage}%)
                  </p>
                </div>
              </div>

              <div className="text-right">
                <p className={`text-lg font-black ${index === 0 ? 'text-indigo-600' : 'text-slate-800'}`}>
                  {user.totalPoints}
                </p>
                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Puntos</p>
              </div>
            </div>
          );
        })}
      </div>

      <div className="p-4 bg-amber-50 rounded-2xl border border-amber-100 text-[11px] text-amber-800 italic text-center">
        * En caso de empate a puntos, lidera quien tenga mayor % de pérdida sobre su peso inicial.
      </div>

      {isAdmin && (
        <div className="p-3 bg-slate-100 rounded-2xl border border-slate-200 text-[10px] text-slate-600 font-medium flex gap-2 items-center">
          <span className="text-base">🛡️</span>
          Modo Administrador: Los nombres reales son visibles solo para ti.
        </div>
      )}

      <div className="mt-8 bg-slate-900 rounded-3xl p-6 text-white overflow-hidden relative shadow-lg">
        <div className="relative z-10">
          <h3 className="text-lg font-bold mb-3">{isFinished ? 'Premio Entregado' : 'Premio Final'}</h3>
          <div className="flex items-center gap-3 bg-white/5 p-4 rounded-2xl border border-white/10 backdrop-blur-sm">
            <div className="w-10 h-10 bg-amber-400/20 rounded-xl flex items-center justify-center text-xl shadow-inner">
              🎁
            </div>
            <p className="text-sm text-slate-200 font-medium leading-tight">
              {config.prizeDescription}
            </p>
          </div>
          <p className="text-[10px] text-slate-400 mt-4 uppercase tracking-[0.2em] font-bold">
            Periodo: {new Date(config.startDate).toLocaleDateString()} - {new Date(config.endDate).toLocaleDateString()}
          </p>
        </div>
      </div>
    </div>
  );
};

export default Leaderboard;

import React, { useEffect, useState } from 'react';
import { User, WeighIn, CompetitionConfig } from '../types';
import { ResponsiveContainer, Tooltip, AreaChart, Area } from 'recharts';
import { getMotivationalMessage, getWelcomeMessage } from '../services/geminiService';

interface DashboardProps {
  user: User;
  leaderboard: User[];
  onAddWeight: (weight: number, ateOut: boolean) => void;
  config: CompetitionConfig;
}

const STORAGE_KEY_MSG = 'pesocompeti_daily_msg';

const Dashboard: React.FC<DashboardProps> = ({ user, leaderboard, onAddWeight, config }) => {
  const [newWeight, setNewWeight] = useState('');
  const [ateOut, setAteOut] = useState(false);
  const [aiMessage, setAiMessage] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  const getLocalDate = (date: Date = new Date()) => {
    const offset = date.getTimezoneOffset();
    const localDate = new Date(date.getTime() - (offset * 60 * 1000));
    return localDate.toISOString().split('T')[0];
  };

  const todayStr = getLocalDate();
  const isFinished = new Date().getTime() > new Date(config.endDate).getTime();

  const fetchMessage = async (force = false) => {
    if (!force) {
      const saved = localStorage.getItem(STORAGE_KEY_MSG);
      if (saved) {
        const { userId, date, message } = JSON.parse(saved);
        if (userId === user.id && date === todayStr) {
          setAiMessage(message);
          return;
        }
      }
    }

    setLoadingAi(true);
    const isNewUser = user.history.length === 0;
    const msg = isNewUser 
      ? await getWelcomeMessage(user) 
      : await getMotivationalMessage(user, leaderboard);

    if (msg) {
      setAiMessage(msg);
      localStorage.setItem(STORAGE_KEY_MSG, JSON.stringify({
        userId: user.id,
        date: todayStr,
        message: msg
      }));
    }
    setLoadingAi(false);
  };

  useEffect(() => {
    fetchMessage();
  }, [user.id]);

  const hasRegisteredToday = user.history.some(h => h.date === todayStr);

  const getWeeklyConsistency = () => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return getLocalDate(d);
    });
    const count = user.history.filter(h => last7Days.includes(h.date)).length;
    return { count, percentage: (count / 7) * 100 };
  };

  const consistency = getWeeklyConsistency();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (hasRegisteredToday || isFinished) return;
    const weight = parseFloat(newWeight.replace(',', '.'));
    if (!isNaN(weight) && weight > 0) {
      onAddWeight(weight, ateOut);
      setNewWeight('');
      setAteOut(false);
    }
  };

  const chartData = user.history.map((h, index) => {
    let accumulated = 0;
    for(let i=0; i<=index; i++) accumulated += user.history[i].delta;
    return {
      name: `S${index}`,
      pérdida: Math.abs(accumulated).toFixed(1),
      puntos: h.points
    };
  });

  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr);
    return date.toLocaleDateString('es-ES', { day: 'numeric', month: 'short' });
  };

  return (
    <div className="space-y-6 pb-24">
      {/* Banner Motivacional IA */}
      <div className={`bg-gradient-to-br ${isFinished ? 'from-amber-500 to-orange-600' : 'from-indigo-500 to-purple-600'} rounded-3xl p-6 text-white shadow-xl relative overflow-hidden transition-all duration-700`}>
        <div className="relative z-10">
          <div className="flex justify-between items-center mb-1">
            <p className="text-white/80 text-sm font-medium">{isFinished ? 'Logros Finales' : 'Coach IA'}</p>
            {!isFinished && (
              <div className="flex items-center gap-2">
                <button onClick={() => fetchMessage(true)} disabled={loadingAi} className={`p-1.5 bg-white/10 rounded-full hover:bg-white/20 ${loadingAi ? 'animate-spin opacity-50' : ''}`}>
                  <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" /></svg>
                </button>
                <p className="text-[10px] text-white/60 font-bold uppercase tracking-widest">{consistency.count}/7 Días</p>
              </div>
            )}
          </div>
          {!isFinished && (
            <div className="w-full h-1 bg-white/10 rounded-full mb-4 overflow-hidden">
              <div className="h-full bg-amber-400 transition-all duration-1000" style={{ width: `${consistency.percentage}%` }}></div>
            </div>
          )}

          <div className="min-h-[4rem] flex items-center">
            {loadingAi ? (
              <div className="flex gap-1">
                <div className="w-2 h-2 bg-white/40 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-white/40 rounded-full animate-bounce [animation-delay:0.2s]"></div>
                <div className="w-2 h-2 bg-white/40 rounded-full animate-bounce [animation-delay:0.4s]"></div>
              </div>
            ) : (
              <h2 className="text-xl font-bold italic leading-tight">
                {isFinished ? `¡Reto completado, ${user.pseudonym}! Has logrado una transformación increíble de ${user.totalWeightLoss.toFixed(1)}kg.` : aiMessage}
              </h2>
            )}
          </div>

          <div className="grid grid-cols-2 gap-4 mt-4">
            <div className="bg-white/10 backdrop-blur-md rounded-2xl p-3 border border-white/5">
              <p className="text-[10px] text-white/70 uppercase font-bold">Puntos Finales</p>
              <p className="text-xl font-bold">{user.totalPoints} pts</p>
            </div>
            <div className="bg-white/10 backdrop-blur-md rounded-2xl p-3 border border-white/5">
              <p className="text-[10px] text-white/70 uppercase font-bold">Variación Total</p>
              <p className="text-xl font-bold">{user.totalWeightLoss.toFixed(1)} kg</p>
            </div>
          </div>
        </div>
      </div>

      {/* Gráfico de Evolución */}
      <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
          <svg className="w-5 h-5 text-indigo-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
          Tu Historial Visual
        </h3>
        <div className="h-48 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={chartData}>
              <defs>
                <linearGradient id="colorLoss" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3}/><stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                </linearGradient>
              </defs>
              <Tooltip contentStyle={{ borderRadius: '20px', border: 'none', boxShadow: '0 10px 25px -5px rgba(0,0,0,0.1)', fontSize: '12px' }} itemStyle={{ fontWeight: 'bold', color: '#6366f1' }} />
              <Area type="monotone" dataKey="pérdida" stroke="#6366f1" strokeWidth={4} fillOpacity={1} fill="url(#colorLoss)" />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Formulario de Registro o Mensaje de Cierre */}
      <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
           <svg className="w-5 h-5 text-indigo-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
          {isFinished ? 'Reto Finalizado' : 'Registro Diario'}
        </h3>

        {isFinished ? (
          <div className="bg-slate-50 border border-slate-100 rounded-3xl p-6 text-center">
            <div className="text-4xl mb-3">🏁</div>
            <p className="text-slate-800 font-bold text-lg mb-1">¡Periodo cerrado!</p>
            <p className="text-slate-500 text-sm">El tiempo de este reto ha terminado. Consulta el ranking para ver quién ha ganado el premio.</p>
          </div>
        ) : hasRegisteredToday ? (
          <div className="bg-emerald-50 border border-emerald-100 rounded-3xl p-6 text-center animate-in zoom-in-95 duration-300">
            <div className="w-16 h-16 bg-emerald-500 rounded-full flex items-center justify-center text-white text-2xl mx-auto mb-4 shadow-lg shadow-emerald-100">✓</div>
            <p className="text-emerald-800 font-bold text-lg mb-1">¡Peso guardado!</p>
            <p className="text-emerald-600 text-sm">Ya has cumplido con tu registro hoy. ¡Vuelve mañana!</p>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="flex gap-2">
              <div className="relative flex-1">
                <input type="number" step="0.1" inputMode="decimal" value={newWeight} onChange={(e) => setNewWeight(e.target.value)} placeholder="Tu peso hoy..." className="w-full bg-slate-50 border-none rounded-2xl py-3.5 px-5 text-slate-700 font-medium focus:ring-2 focus:ring-indigo-500 transition-all outline-none" />
                <span className="absolute right-4 top-3.5 text-slate-400 font-bold">kg</span>
              </div>
              <button type="submit" className="bg-indigo-600 text-white font-bold py-3.5 px-6 rounded-2xl hover:bg-indigo-700 active:scale-95 transition-all shadow-lg shadow-indigo-100">Enviar</button>
            </div>
            <label className="flex items-center gap-3 p-4 bg-slate-50 rounded-2xl cursor-pointer select-none active:bg-slate-100 transition-colors border border-transparent active:border-slate-200">
              <input type="checkbox" checked={ateOut} onChange={(e) => setAteOut(e.target.checked)} className="w-5 h-5 rounded-lg border-slate-300 text-indigo-600 focus:ring-indigo-500" />
              <div className="flex-1">
                <p className="text-sm font-bold text-slate-700">¿Comiste fuera ayer?</p>
                <p className="text-[10px] text-indigo-500 uppercase font-bold tracking-tight">¡Bono Social de +50 pts!</p>
              </div>
              <span className="text-2xl">🍽️</span>
            </label>
          </form>
        )}
      </div>

      {/* Histórico de Datos */}
      <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100">
        <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center gap-2">
          <svg className="w-5 h-5 text-indigo-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
          Registros Pasados
        </h3>
        <div className="space-y-3">
          {[...user.history].reverse().map((entry) => (
            <div key={entry.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100 transition-all hover:bg-slate-100/50">
              <div className="flex items-center gap-3">
                <div className="bg-white w-10 h-10 rounded-xl flex flex-col items-center justify-center shadow-sm border border-slate-100">
                  <span className="text-[10px] font-black uppercase text-indigo-600 leading-none">{formatDate(entry.date).split(' ')[1]}</span>
                  <span className="text-sm font-bold text-slate-800 leading-tight">{formatDate(entry.date).split(' ')[0]}</span>
                </div>
                <div>
                  <p className="text-sm font-black text-slate-800">{entry.weight.toFixed(1)} kg</p>
                  <p className={`text-[10px] font-bold uppercase ${entry.delta <= 0 ? 'text-emerald-500' : 'text-rose-500'}`}>
                    {entry.delta > 0 ? '+' : ''}{entry.delta.toFixed(1)} kg {entry.ateOut ? ' • 🍽️' : ''}
                  </p>
                </div>
              </div>
              <div className="text-right">
                <p className="text-sm font-black text-indigo-600">+{entry.points}</p>
                <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Puntos</p>
              </div>
            </div>
          ))}
          <div className="flex items-center justify-between p-4 bg-indigo-50/50 rounded-2xl border border-indigo-200/50 relative overflow-hidden">
            <div className="flex items-center gap-3 relative z-10">
              <div className="bg-indigo-600 w-10 h-10 rounded-xl flex flex-col items-center justify-center shadow-sm text-white">
                <span className="text-[10px] font-black uppercase leading-none opacity-80">{formatDate(config.startDate).split(' ')[1]}</span>
                <span className="text-sm font-bold leading-tight">{formatDate(config.startDate).split(' ')[0]}</span>
              </div>
              <div><p className="text-sm font-black text-slate-800">{user.initialWeight.toFixed(1)} kg</p><p className="text-[10px] font-bold uppercase text-indigo-600 flex items-center gap-1">🚩 Punto de Partida</p></div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import { initializeApp } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-app.js";
import { getFirestore } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";
import { getAuth } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-auth.js";

// Estos valores deben ser reemplazados por los de tu consola de Firebase
// (Project Settings > General > Your Apps > Web App)
const firebaseConfig = {
  apiKey: "TU_API_KEY",
  authDomain: "TU_PROYECTO.firebaseapp.com",
  projectId: "TU_PROYECTO",
  storageBucket: "TU_PROYECTO.appspot.com",
  messagingSenderId: "TU_SENDER_ID",
  appId: "TU_APP_ID"
};

const app = initializeApp(firebaseConfig);
export const db = getFirestore(app);
export const auth = getAuth(app);

import React, { useState, useEffect } from 'react';
import { User, WeighIn, CompetitionConfig } from './types';
import { INITIAL_RULES, FRUITS } from './constants';
import TopNav from './components/TopNav';
import Dashboard from './components/Dashboard';
import Leaderboard from './components/Leaderboard';
import Rules from './components/Rules';
import AdminSettings from './components/AdminSettings';
import LandingPage from './components/LandingPage';

// Firebase imports
import { db, auth } from './services/firebase';
import { 
  collection, 
  onSnapshot, 
  doc, 
  setDoc, 
  updateDoc, 
  getDoc,
  query,
  orderBy 
} from "https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore.js";
import { onAuthStateChanged, signOut } from "https://www.gstatic.com/firebasejs/10.8.0/firebase-auth.js";

type View = 'dashboard' | 'leaderboard' | 'rules' | 'admin' | 'welcome';

const App: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeView, setActiveView] = useState<View>('dashboard');
  const [isLoading, setIsLoading] = useState(true);
  const [competitionConfig, setCompetitionConfig] = useState<CompetitionConfig | null>(null);

  // 1. Escuchar Cambios de Autenticación
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      if (firebaseUser) {
        // El usuario está logueado, buscamos sus datos en Firestore
        const userRef = doc(db, "users", firebaseUser.uid);
        const userSnap = await getDoc(userRef);
        if (userSnap.exists()) {
          setCurrentUser({ id: firebaseUser.uid, ...userSnap.data() } as User);
        }
      } else {
        setCurrentUser(null);
        setActiveView('welcome');
      }
      setIsLoading(false);
    });
    return () => unsubscribe();
  }, []);

  // 2. Escuchar Ranking y Configuración en tiempo real
  useEffect(() => {
    // Escuchar Usuarios
    const q = query(collection(db, "users"), orderBy("totalPoints", "desc"));
    const unsubUsers = onSnapshot(q, (snapshot) => {
      const usersData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as User));
      setUsers(usersData);

      // Actualizar el currentUser local si hay cambios en el servidor
      if (auth.currentUser) {
        const me = usersData.find(u => u.id === auth.currentUser?.uid);
        if (me) setCurrentUser(me);
      }
    });

    // Escuchar Configuración del Reto
    const unsubConfig = onSnapshot(doc(db, "settings", "competition"), (doc) => {
      if (doc.exists()) {
        setCompetitionConfig(doc.data() as CompetitionConfig);
      }
    });

    return () => {
      unsubUsers();
      unsubConfig();
    };
  }, []);

  const getLocalDate = (date = new Date()) => {
    const offset = date.getTimezoneOffset();
    const localDate = new Date(date.getTime() - (offset * 60 * 1000));
    return localDate.toISOString().split('T')[0];
  };

  const handleAddWeight = async (weight: number, ateOut: boolean) => {
    if (!currentUser || !competitionConfig) return;

    const now = new Date();
    const todayStr = getLocalDate(now);
    const alreadyRegistered = currentUser.history.some(h => h.date === todayStr);

    if (alreadyRegistered) {
      alert("Ya has registrado tu peso hoy.");
      return;
    }

    const lastWeighIn = currentUser.history.length > 0 
      ? currentUser.history[currentUser.history.length - 1] 
      : { weight: currentUser.initialWeight, delta: 0, date: competitionConfig.startDate };

    const delta = weight - lastWeighIn.weight;
    let earnedPoints = 10; 
    let messages: string[] = [];

    if (delta <= -0.11) {
      earnedPoints += Math.floor(Math.abs(delta) * 100); 
    } else if (delta > 0.1) {
      earnedPoints -= Math.floor(delta * 150); 
    } else {
      earnedPoints += 5;
      messages.push("⚖️ ¡Bono Mantenimiento! (+5 pts)");
    }

    if (ateOut) {
      earnedPoints += 50;
      messages.push("🍽️ ¡Bono Social! (+50 pts)");
    }

    if (now.getHours() < 10) {
      earnedPoints += 5;
      messages.push("🌅 ¡Bono Madrugador! (+5 pts)");
    }

    const newLoss = currentUser.initialWeight - weight;
    const oldLoss = currentUser.totalWeightLoss;
    if (Math.floor(newLoss) > Math.floor(oldLoss) && newLoss > 0) {
      earnedPoints += 100;
      messages.push(`🎉 ¡HITO! Perder ${Math.floor(newLoss)}kg. (+100 pts)`);
    }

    const newWeighIn: WeighIn = {
      id: Math.random().toString(36).substr(2, 9),
      date: todayStr,
      weight: weight,
      delta: delta,
      points: earnedPoints,
      ateOut: ateOut
    };

    const updatedData = {
      history: [...currentUser.history, newWeighIn],
      totalPoints: Math.max(0, currentUser.totalPoints + earnedPoints),
      totalWeightLoss: newLoss
    };

    // PERSISTENCIA EN FIRESTORE
    try {
      await updateDoc(doc(db, "users", currentUser.id), updatedData);
      alert(`¡Peso registrado! +${earnedPoints} pts.\n${messages.join('\n')}`);
    } catch (e) {
      alert("Error al guardar en la nube.");
    }
  };

  const handleRegister = async (userData: { realName: string, pseudonym: string, initialWeight: number }) => {
    // La creación de usuario ahora se gestiona en LandingPage mediante Firebase Auth
    // Esta función se llama tras el éxito del Auth para crear el documento en Firestore
    const fruit = FRUITS[Math.floor(Math.random() * FRUITS.length)];
    const newUser: Omit<User, 'id'> = {
      realName: userData.realName,
      pseudonym: userData.pseudonym,
      initialWeight: userData.initialWeight,
      avatar: `https://img.icons8.com/fluency/200/${fruit}.png`,
      history: [],
      totalPoints: 0,
      totalWeightLoss: 0,
      isAdmin: users.length === 0 // El primero en entrar es Admin
    };

    if (auth.currentUser) {
      await setDoc(doc(db, "users", auth.currentUser.uid), newUser);
      setActiveView('dashboard');
    }
  };

  const handleUpdateConfig = async (newConfig: CompetitionConfig) => {
    await setDoc(doc(db, "settings", "competition"), newConfig);
    alert("Configuración global actualizada");
  };

  const handleLogout = () => {
    signOut(auth);
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-indigo-600"></div>
      </div>
    );
  }

  if (!currentUser || !competitionConfig) {
    return (
      <div className="min-h-screen bg-slate-50 max-w-md mx-auto shadow-2xl flex flex-col">
        <TopNav currentUser={null} onLogout={() => {}} />
        <main className="flex-1 p-4 overflow-y-auto">
          <LandingPage onRegister={handleRegister} />
        </main>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 max-w-md mx-auto shadow-2xl relative flex flex-col">
      <TopNav currentUser={currentUser} onLogout={handleLogout} />
      <main className="flex-1 p-4 overflow-y-auto">
        {activeView === 'dashboard' && (
          <Dashboard user={currentUser} leaderboard={users} onAddWeight={handleAddWeight} config={competitionConfig} />
        )}
        {activeView === 'leaderboard' && (
          <Leaderboard users={users} currentUser={currentUser} config={competitionConfig} />
        )}
        {activeView === 'rules' && (
          <Rules rules={INITIAL_RULES} />
        )}
        {activeView === 'admin' && currentUser.isAdmin && (
          <AdminSettings 
            config={competitionConfig} onUpdateConfig={handleUpdateConfig} 
            users={users} 
            onRemoveUser={async (id) => { /* logic */ }} 
            onAddUser={async (data) => { /* logic */ }} 
            onToggleAdmin={async (id) => { /* logic */ }}
